pub const SCHEDULER_SNAPSHOT_SCHEMA_VERSION: u32 = 1;

// Snapshot payloads are transient oracle records. Keep their public value shape
// stable instead of adding allocation to smaller variants for a size heuristic.
#[allow(clippy::large_enum_variant)]
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SchedulerSnapshotPayload {
    Policy(GpuSchedulerPolicy),
    Stockham(StockhamUploadSchedule),
    DoubleDoubleStockham(crate::scheduler::DoubleDoubleStockhamUploadSchedule),
    /// DD `VkFFTScheduler` upload fields for axes whose Rust execution tree is recursive
    /// (for example a Bluestein convolution containing a Direct-Rader component).
    /// Upstream still reports these fields under the `dd-stockham` snapshot kind even
    /// though the executable Rust child correctly routes through the Rader planner.
    DoubleDoubleRecursiveUpload {
        sequence_len: usize,
        batch_count: usize,
        used_shared_memory_bytes: usize,
        max_sequence_len_shared: usize,
        max_sequence_len_strided: usize,
        register_boost: usize,
        upload_count: usize,
        axis_split: Vec<usize>,
    },
    RealShape {
        sequence_len: usize,
        batch_count: usize,
        scheduled_fft_len: usize,
        algorithm: RealFftAlgorithm,
        callback_forced: bool,
        big_sequence_even_r2c: bool,
    },
    Rader(RaderFftRegisterSchedule),
    RaderUpload {
        sequence_len: usize,
        force_rader_two_upload: bool,
        upload_count: usize,
        axis_split: Vec<usize>,
    },
    RaderParent {
        sequence_len: usize,
        batch_count: usize,
        upload_count: usize,
        axis_split: Vec<usize>,
        final_min_registers: usize,
        min_rader_fft_thread_num: usize,
        threads_per_transform: usize,
    },
    RaderMixedParent {
        sequence_len: usize,
        batch_count: usize,
        direct_primes: Vec<usize>,
        fft_primes: Vec<usize>,
        threads_per_transform: usize,
    },
    AxisBlock {
        sequence_len: usize,
        batch_count: usize,
        axis_upload_id: Option<usize>,
        transform_count: usize,
        block: StockhamAxisBlockSchedule,
    },
    Bluestein {
        sequence_len: usize,
        batch_count: usize,
        padded_len: usize,
    },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SchedulerSnapshotRecord {
    pub case_name: String,
    pub backend: Backend,
    pub vendor: GpuVendor,
    pub precision: Precision,
    pub device: DeviceProfile,
    pub payload: SchedulerSnapshotPayload,
}

impl SchedulerSnapshotRecord {
    pub fn kind(&self) -> &'static str {
        match self.payload {
            SchedulerSnapshotPayload::Policy(_) => "policy",
            SchedulerSnapshotPayload::Stockham(_) => "stockham",
            SchedulerSnapshotPayload::DoubleDoubleStockham(_)
            | SchedulerSnapshotPayload::DoubleDoubleRecursiveUpload { .. } => "dd-stockham",
            SchedulerSnapshotPayload::RealShape { .. } => "real-shape",
            SchedulerSnapshotPayload::Rader(_) => "rader",
            SchedulerSnapshotPayload::RaderUpload { .. } => "rader-upload",
            SchedulerSnapshotPayload::RaderParent { .. } => "rader-parent",
            SchedulerSnapshotPayload::RaderMixedParent { .. } => "rader-mixed-parent",
            SchedulerSnapshotPayload::AxisBlock { .. } => "axis-block",
            SchedulerSnapshotPayload::Bluestein { .. } => "bluestein",
        }
    }

    /// Render one deterministic schema-v1 JSON object suitable for JSONL diffing.
    pub fn to_json_line(&self) -> String {
        let mut out = String::with_capacity(1024);
        out.push('{');
        write!(
            &mut out,
            "\"schema_version\":{SCHEDULER_SNAPSHOT_SCHEMA_VERSION},"
        )
        .unwrap();
        out.push_str("\"upstream_commit\":");
        push_json_string(&mut out, UPSTREAM_VKFFT_COMMIT);
        out.push_str(",\"case\":");
        push_json_string(&mut out, &self.case_name);
        out.push_str(",\"kind\":");
        push_json_string(&mut out, self.kind());
        out.push_str(",\"backend\":");
        push_json_string(&mut out, backend_name(self.backend));
        out.push_str(",\"vendor\":");
        push_json_string(&mut out, &vendor_name(self.vendor));
        out.push_str(",\"precision\":");
        push_json_string(&mut out, precision_name(self.precision));
        out.push_str(",\"device\":{");
        write!(
            &mut out,
            "\"shared_memory_bytes\":{},\"shared_memory_pow2_bytes\":{},\"max_threads_per_block\":{},",
            self.device.shared_memory_bytes,
            self.device.shared_memory_pow2_bytes,
            self.device.max_threads_per_block
        )
        .unwrap();
        out.push_str("\"max_workgroup_size\":");
        push_usize_array(&mut out, &self.device.max_workgroup_size);
        write!(
            &mut out,
            ",\"coalesced_memory_bytes\":{},\"shared_banks\":{},\"supports_f64\":{}",
            self.device.coalesced_memory_bytes, self.device.shared_banks, self.device.supports_f64
        )
        .unwrap();
        out.push_str("},\"payload\":");
        render_payload(&mut out, &self.payload);
        out.push('}');
        out
    }
}

/// One parameterized Rader-upload scheduler probe. Unlike the fixed snapshot corpus,
/// these probes are intended for broad differential sweeps generated outside the crate.
/// The external pinned-upstream harness remains the source of truth; this value only
/// describes the Rust candidate input using the same scheduler-visible knobs.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SchedulerRaderUploadProbe {
    pub case_name: String,
    pub sequence_len: usize,
    pub precision: Precision,
    pub device: DeviceProfile,
    pub strided_axis: bool,
    pub fastest_axis_len: usize,
    pub bandwidth_boost: usize,
    pub batch_count: usize,
    pub grouped_batch_override: Option<usize>,
    pub perform_zero_padding: bool,
    pub min_rader_direct_prime: usize,
    pub max_rader_direct_prime: usize,
    pub min_rader_fft_prime: usize,
    pub max_rader_fft_prime: usize,
}

/// Physical higher-axis context for parameterized AxisBlock probes. Keeping this
/// separate preserves the original logical/classification probe API while allowing
/// axis-id >= 2 differential witnesses to model upstream's literal `groupedBatch[1]`
/// gate independently from `groupedBatch[axis_id]`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SchedulerPhysicalAxisProbeContext {
    pub upstream_axis_id: usize,
    pub middle_axis_len: usize,
    pub axis1_grouped_batch_override: Option<usize>,
}

impl SchedulerPhysicalAxisProbeContext {
    fn legacy(probe: &SchedulerRaderUploadProbe) -> Self {
        Self {
            upstream_axis_id: usize::from(probe.strided_axis),
            middle_axis_len: 1,
            axis1_grouped_batch_override: if probe.strided_axis {
                probe.grouped_batch_override
            } else {
                None
            },
        }
    }
}

/// Device-aware algorithm classification for one parameterized scheduler probe.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SchedulerAxisClassification {
    Stockham,
    Rader {
        direct_primes: Vec<usize>,
        fft_primes: Vec<usize>,
    },
    Bluestein {
        padded_len: usize,
    },
}

/// Classify one parameterized C2C axis through the normal device-aware planner.
pub fn scheduler_axis_classification_probe(
    probe: &SchedulerRaderUploadProbe,
) -> Result<SchedulerAxisClassification> {
    if probe.case_name.is_empty() || probe.sequence_len == 0 || probe.batch_count == 0 {
        return Err(VkFftError::InvalidKernelIr(
            "parameterized scheduler probe requires a non-empty case, sequence, and batch",
        ));
    }
    let mut tuning = PlannerTuning::for_device(probe.device, probe.precision);
    tuning.min_rader_direct_prime = probe.min_rader_direct_prime;
    tuning.max_rader_direct_prime = probe.max_rader_direct_prime;
    tuning.min_rader_fft_prime = probe.min_rader_fft_prime;
    tuning.max_rader_fft_prime = probe.max_rader_fft_prime;
    tuning.validate()?;
    let axis_class = if probe.strided_axis {
        C2cDeviceAxisClass::Strided
    } else {
        C2cDeviceAxisClass::Contiguous
    };
    let mut config = FftConfig::new(vec![probe.sequence_len])
        .with_batch_count(probe.batch_count)
        .with_precision(probe.precision)
        .with_tuning(tuning)
        .with_bandwidth_boost(probe.bandwidth_boost);
    if let Some(grouped_batch) = probe.grouped_batch_override {
        config = config.with_grouped_batch(0, grouped_batch)?;
    }
    if probe.perform_zero_padding {
        config = config.with_zero_padding(0, 0, 1)?;
    }
    let plan = FftPlan::build_c2c_child_for_device(config, probe.device, axis_class)?;
    let axis = plan.axes.first().ok_or(VkFftError::InvalidKernelIr(
        "parameterized scheduler probe produced no planned axis",
    ))?;
    match &axis.algorithm {
        AxisAlgorithm::Stockham { .. } => Ok(SchedulerAxisClassification::Stockham),
        AxisAlgorithm::Bluestein {
            convolution_len, ..
        } => Ok(SchedulerAxisClassification::Bluestein {
            padded_len: *convolution_len,
        }),
        AxisAlgorithm::Rader { primes, .. } => {
            let mut direct_primes = Vec::new();
            let mut fft_primes = Vec::new();
            for prime in primes {
                let target = match prime.mode {
                    RaderMode::FftConvolution { .. } => &mut fft_primes,
                    RaderMode::DirectMultiplication => &mut direct_primes,
                };
                if !target.contains(&prime.prime) {
                    target.push(prime.prime);
                }
            }
            direct_primes.sort_unstable();
            fft_primes.sort_unstable();
            Ok(SchedulerAxisClassification::Rader {
                direct_primes,
                fft_primes,
            })
        }
    }
}

/// Build one Rust-side scheduler candidate for a parameterized Rader-upload probe.
///
/// Prime classification deliberately comes from the normal device-aware planner rather
/// than from the sweep generator. This lets the differential catch both classification
/// and upload-splitting mismatches while keeping the generated probe file independent of
/// Rust implementation details. Whole-axis Bluestein cases are rejected because their
/// scheduler contract belongs to the dedicated Bluestein snapshot family.
pub fn scheduler_rader_upload_probe_record(
    probe: &SchedulerRaderUploadProbe,
) -> Result<SchedulerSnapshotRecord> {
    let (fft_rader_primes, direct_rader_primes) = match scheduler_axis_classification_probe(probe)?
    {
        SchedulerAxisClassification::Stockham => (Vec::new(), Vec::new()),
        SchedulerAxisClassification::Rader {
            direct_primes,
            fft_primes,
        } => (fft_primes, direct_primes),
        SchedulerAxisClassification::Bluestein { .. } => {
            return Err(VkFftError::UnsupportedKernelPath(
                "parameterized Rader-upload probe promoted the whole axis to Bluestein",
            ));
        }
    };

    rader_upload_or_single_record_with_axis_context(
        &probe.case_name,
        probe.precision,
        probe.device,
        probe.sequence_len,
        &fft_rader_primes,
        &direct_rader_primes,
        StockhamUploadAxisContext {
            strided_axis: probe.strided_axis,
            bandwidth_boost: probe.bandwidth_boost,
            ..StockhamUploadAxisContext::default()
        },
    )
}

/// Build physical upload records from the actual recursive IR selected for a parameterized
/// Rader-upload probe. Contiguous probes expose the axis-0 blocks directly; strided probes
/// retag the same materialized uploads through the production higher-axis path using the
/// fastest physical tensor extent carried by the shared TSV contract.
pub fn scheduler_rader_upload_axis_block_probe_records(
    probe: &SchedulerRaderUploadProbe,
) -> Result<Vec<SchedulerSnapshotRecord>> {
    scheduler_rader_upload_axis_block_probe_records_with_context(
        probe,
        SchedulerPhysicalAxisProbeContext::legacy(probe),
    )
}

/// Explicit physical-axis form used by pinned-upstream differential probes that need
/// to distinguish `groupedBatch[1]` from `groupedBatch[axis_id]` on axis id 2.
pub fn scheduler_rader_upload_axis_block_probe_records_with_context(
    probe: &SchedulerRaderUploadProbe,
    physical_axis: SchedulerPhysicalAxisProbeContext,
) -> Result<Vec<SchedulerSnapshotRecord>> {
    if physical_axis.upstream_axis_id > 2
        || probe.strided_axis != (physical_axis.upstream_axis_id > 0)
        || (physical_axis.upstream_axis_id > 0 && probe.fastest_axis_len == 0)
        || (physical_axis.upstream_axis_id > 1 && physical_axis.middle_axis_len == 0)
    {
        return Err(VkFftError::InvalidKernelIr(
            "parameterized physical Rader probe has inconsistent higher-axis geometry",
        ));
    }
    let classification = scheduler_axis_classification_probe(probe)?;
    if !matches!(classification, SchedulerAxisClassification::Rader { .. }) {
        return Err(VkFftError::UnsupportedKernelPath(
            "parameterized physical Rader-upload probe requires a Rader axis",
        ));
    }
    let mut tuning = PlannerTuning::for_device(probe.device, probe.precision);
    tuning.min_rader_direct_prime = probe.min_rader_direct_prime;
    tuning.max_rader_direct_prime = probe.max_rader_direct_prime;
    tuning.min_rader_fft_prime = probe.min_rader_fft_prime;
    tuning.max_rader_fft_prime = probe.max_rader_fft_prime;
    tuning.validate()?;

    let axis_class = if probe.strided_axis {
        C2cDeviceAxisClass::Strided
    } else {
        C2cDeviceAxisClass::Contiguous
    };
    let independent_lines = match physical_axis.upstream_axis_id {
        0 => 1,
        1 => probe.fastest_axis_len,
        2 => probe
            .fastest_axis_len
            .checked_mul(physical_axis.middle_axis_len)
            .ok_or(VkFftError::ArithmeticOverflow {
                operation: "parameterized axis2 Rader probe independent-line count",
            })?,
        _ => unreachable!("validated upstream physical axis id"),
    };
    let transform_batch_count =
        probe
            .batch_count
            .checked_mul(independent_lines)
            .ok_or(VkFftError::ArithmeticOverflow {
                operation: "parameterized physical Rader probe transform batch count",
            })?;
    // Match the production ND builder: a higher-axis 1D child owns one transform
    // batch for every independent fastest-axis line. Keeping this IR at batch=1 and
    // multiplying only the rendered record counts can under-size physical grouping
    // whenever the fastest extent exceeds a component's base transform count.
    let mut config = FftConfig::new(vec![probe.sequence_len])
        .with_batch_count(transform_batch_count)
        .with_precision(probe.precision)
        .with_tuning(tuning)
        .with_bandwidth_boost(probe.bandwidth_boost);
    if let Some(grouped_batch) = probe.grouped_batch_override {
        config = config.with_grouped_batch(0, grouped_batch)?;
    }
    if probe.perform_zero_padding {
        config = config.with_zero_padding(0, 0, 1)?;
    }

    if probe.precision == Precision::DoubleDouble {
        let plan = FftPlan::build_c2c_child_for_device(config, probe.device, axis_class)?;
        let mut ir =
            crate::double_double_recursive_ir::DoubleDoubleRecursiveFftIr::build_for_device(
                &plan,
                Direction::Forward,
                probe.device,
            )?;
        if physical_axis.upstream_axis_id > 0 {
            ir = ir.with_other_axis_physical_blocks(
                probe.fastest_axis_len,
                probe.grouped_batch_override,
                physical_axis.axis1_grouped_batch_override,
                probe.device,
            )?;
        }
        let schedule =
            ir.rader_forced_upload_schedule
                .as_ref()
                .ok_or(VkFftError::UnsupportedKernelPath(
                    "parameterized DD physical Rader probe requires a multi-upload schedule",
                ))?;
        let records = match schedule.upload_count {
            2 => forced_rader_two_upload_axis_block_records_from_ir(
                &probe.case_name,
                probe.device,
                &ir,
            )?,
            3 => parameterized_dd_three_upload_axis_block_records(
                &probe.case_name,
                probe.device,
                &ir,
            )?,
            _ => {
                return Err(VkFftError::UnsupportedKernelPath(
                    "parameterized DD physical Rader probe requires two or three uploads",
                ));
            }
        };
        return Ok(records);
    }

    let plan = FftPlan::build_c2c_child_for_device(config, probe.device, axis_class)?;
    let mut ir = RecursiveFftIr::build(&plan, Direction::Forward, probe.device)?;
    if physical_axis.upstream_axis_id > 0 {
        ir = if probe.grouped_batch_override.is_some() {
            ir.with_other_axis_single_upload_block_with_grouped_batch(
                probe.fastest_axis_len,
                probe.grouped_batch_override,
                physical_axis.axis1_grouped_batch_override,
                probe.device,
            )?
        } else {
            ir.with_other_axis_single_upload_block(probe.fastest_axis_len, probe.device)?
        };
    }
    let four_step = ir
        .four_step_plan
        .as_ref()
        .ok_or(VkFftError::UnsupportedKernelPath(
            "parameterized physical Rader probe requires a multi-upload Four-step plan",
        ))?;
    if four_step.uploads.len() < 2 {
        return Err(VkFftError::UnsupportedKernelPath(
            "parameterized physical Rader probe requires at least two uploads",
        ));
    }
    let mut records = Vec::with_capacity(four_step.uploads.len());
    for upload in &four_step.uploads {
        let block = upload.axis_block.ok_or(VkFftError::UnsupportedKernelPath(
            "parameterized physical Rader upload is missing its axis block",
        ))?;
        let transform_count = upload.transform_count;
        records.push(axis_block_record(
            &format!("{}-u{}", probe.case_name, upload.axis_upload_id),
            probe.precision,
            probe.device,
            upload.fft_len,
            transform_count,
            Some(upload.axis_upload_id),
            transform_count,
            block,
        ));
    }
    records.sort_by_key(|record| match record.payload {
        SchedulerSnapshotPayload::AxisBlock { axis_upload_id, .. } => axis_upload_id.unwrap_or(0),
        _ => 0,
    });
    Ok(records)
}

fn parameterized_dd_three_upload_axis_block_records(
    case_prefix: &str,
    device: DeviceProfile,
    ir: &crate::double_double_recursive_ir::DoubleDoubleRecursiveFftIr,
) -> Result<Vec<SchedulerSnapshotRecord>> {
    let components = ir.forced_rader_three_upload_mapped_components()?.ok_or(
        VkFftError::UnsupportedKernelPath(
            "parameterized DD Rader probe must materialize three mapped components",
        ),
    )?;
    let mut records = Vec::with_capacity(3);
    for component in components {
        let upload_id = component.upload_id();
        let sequence_len = component.logical_len();
        let (batch_count, block) = match &component {
            crate::double_double_recursive_ir::DoubleDoubleForcedRaderThreeUploadComponentIr::Stockham { ir, .. } => {
                (ir.batch_count, ir.axis_batch_block)
            }
            crate::double_double_recursive_ir::DoubleDoubleForcedRaderThreeUploadComponentIr::Recursive { ir, .. } => {
                (ir.batch_count(), recursive_node_axis_block(ir))
            }
        };
        let block = block.ok_or(VkFftError::UnsupportedKernelPath(match upload_id {
            0 => "parameterized DD three-upload u0 component is missing its physical block",
            1 => "parameterized DD three-upload u1 component is missing its physical block",
            2 => "parameterized DD three-upload u2 component is missing its physical block",
            _ => "parameterized DD three-upload component is missing its physical block",
        }))?;
        records.push(axis_block_record(
            &format!("{case_prefix}-u{upload_id}"),
            Precision::DoubleDouble,
            device,
            sequence_len,
            batch_count,
            Some(upload_id),
            batch_count,
            block,
        ));
    }
    records.sort_by_key(|record| match record.payload {
        SchedulerSnapshotPayload::AxisBlock { axis_upload_id, .. } => axis_upload_id.unwrap_or(0),
        _ => 0,
    });
    Ok(records)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SchedulerSnapshotMismatch {
    pub case_name: Option<String>,
    pub path: Option<String>,
    pub message: String,
}

impl fmt::Display for SchedulerSnapshotMismatch {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.message)?;
        if let Some(case_name) = &self.case_name {
            write!(formatter, " [case={case_name}]")?;
        }
        if let Some(path) = &self.path {
            write!(formatter, " [path={path}]")?;
        }
        Ok(())
    }
}

impl Error for SchedulerSnapshotMismatch {}

#[derive(Debug)]
struct ParsedReferenceLine<'a> {
    line_number: usize,
    case_name: String,
    kind: String,
    raw: &'a str,
}

/// Compare Rust-generated scheduler candidates against an externally generated upstream
/// JSONL reference. Reference line order is irrelevant; `case` is the stable identity.
///
/// Every non-empty reference line must use this schema version and the crate's pinned
/// upstream commit. Missing, extra, and duplicate cases are rejected. On a scheduler
/// mismatch the returned error reports the first structural JSON path (for example
/// `payload.stage_radices` or `device.shared_memory_bytes`) instead of only a line number.
pub fn compare_upstream_scheduler_snapshot_jsonl(
    reference_jsonl: &str,
    candidate: &[SchedulerSnapshotRecord],
) -> std::result::Result<(), SchedulerSnapshotMismatch> {
    let mut reference_by_case = BTreeMap::new();
    for (line_index, raw_line) in reference_jsonl.lines().enumerate() {
        let line = raw_line.trim();
        if line.is_empty() {
            continue;
        }
        let parsed = parse_reference_line(line, line_index + 1)?;
        if reference_by_case
            .insert(parsed.case_name.clone(), parsed)
            .is_some()
        {
            return Err(snapshot_mismatch(
                None,
                Some("case"),
                format!(
                    "upstream scheduler reference contains duplicate case on line {}",
                    line_index + 1
                ),
            ));
        }
    }
    if reference_by_case.is_empty() {
        return Err(snapshot_mismatch(
            None,
            None,
            "upstream scheduler reference contains no JSONL records",
        ));
    }

    let mut candidate_by_case = BTreeMap::new();
    for record in candidate {
        if candidate_by_case
            .insert(record.case_name.as_str(), record)
            .is_some()
        {
            return Err(snapshot_mismatch(
                Some(&record.case_name),
                Some("case"),
                "Rust scheduler candidate corpus contains a duplicate case",
            ));
        }
    }

    for (case_name, record) in &candidate_by_case {
        let Some(reference) = reference_by_case.remove(*case_name) else {
            return Err(snapshot_mismatch(
                Some(case_name),
                Some("case"),
                "upstream scheduler reference is missing a Rust candidate case",
            ));
        };
        if reference.kind != record.kind() {
            return Err(snapshot_mismatch(
                Some(case_name),
                Some("kind"),
                format!(
                    "scheduler snapshot kind mismatch on reference line {}: upstream={}, rust={}",
                    reference.line_number,
                    reference.kind,
                    record.kind()
                ),
            ));
        }
        let actual = record.to_json_line();
        if let Some(path) = first_json_difference_path(reference.raw, &actual) {
            return Err(snapshot_mismatch(
                Some(case_name),
                Some(&path),
                format!(
                    "scheduler snapshot differs from upstream reference line {}",
                    reference.line_number
                ),
            ));
        }
    }

    if let Some((case_name, reference)) = reference_by_case.into_iter().next() {
        return Err(snapshot_mismatch(
            Some(&case_name),
            Some("case"),
            format!(
                "upstream scheduler reference contains an extra case on line {}",
                reference.line_number
            ),
        ));
    }
    Ok(())
}

fn snapshot_mismatch(
    case_name: Option<&str>,
    path: Option<&str>,
    message: impl Into<String>,
) -> SchedulerSnapshotMismatch {
    SchedulerSnapshotMismatch {
        case_name: case_name.map(str::to_owned),
        path: path.map(str::to_owned),
        message: message.into(),
    }
}

fn parse_reference_line(
    line: &str,
    line_number: usize,
) -> std::result::Result<ParsedReferenceLine<'_>, SchedulerSnapshotMismatch> {
    let fields = parse_json_object_fields(line).map_err(|message| {
        snapshot_mismatch(
            None,
            None,
            format!("invalid scheduler reference JSON on line {line_number}: {message}"),
        )
    })?;
    let field = |name: &str| {
        fields
            .iter()
            .find(|(field_name, _)| field_name == name)
            .map(|(_, value)| *value)
            .ok_or_else(|| {
                snapshot_mismatch(
                    None,
                    Some(name),
                    format!("scheduler reference line {line_number} is missing `{name}`"),
                )
            })
    };

    let schema_version = field("schema_version")?.parse::<u32>().map_err(|_| {
        snapshot_mismatch(
            None,
            Some("schema_version"),
            format!("scheduler reference line {line_number} has a non-integer schema version"),
        )
    })?;
    if schema_version != SCHEDULER_SNAPSHOT_SCHEMA_VERSION {
        return Err(snapshot_mismatch(
            None,
            Some("schema_version"),
            format!(
                "scheduler reference line {line_number} uses schema {schema_version}, expected {SCHEDULER_SNAPSHOT_SCHEMA_VERSION}"
            ),
        ));
    }
    let upstream_commit = decode_json_string(field("upstream_commit")?).map_err(|message| {
        snapshot_mismatch(
            None,
            Some("upstream_commit"),
            format!("scheduler reference line {line_number}: {message}"),
        )
    })?;
    if upstream_commit != UPSTREAM_VKFFT_COMMIT {
        return Err(snapshot_mismatch(
            None,
            Some("upstream_commit"),
            format!(
                "scheduler reference line {line_number} targets upstream commit {upstream_commit}, expected {UPSTREAM_VKFFT_COMMIT}"
            ),
        ));
    }
    let case_name = decode_json_string(field("case")?).map_err(|message| {
        snapshot_mismatch(
            None,
            Some("case"),
            format!("scheduler reference line {line_number}: {message}"),
        )
    })?;
    let kind = decode_json_string(field("kind")?).map_err(|message| {
        snapshot_mismatch(
            Some(&case_name),
            Some("kind"),
            format!("scheduler reference line {line_number}: {message}"),
        )
    })?;
    Ok(ParsedReferenceLine {
        line_number,
        case_name,
        kind,
        raw: line,
    })
}

fn first_json_difference_path(expected: &str, actual: &str) -> Option<String> {
    first_json_difference(expected.trim(), actual.trim(), "", 0)
        .unwrap_or_else(|_| Some("$".into()))
}

fn first_json_difference(
    expected: &str,
    actual: &str,
    prefix: &str,
    depth: usize,
) -> std::result::Result<Option<String>, String> {
    if expected == actual {
        return Ok(None);
    }
    if depth > 32 {
        return Ok(Some(
            if prefix.is_empty() { "$" } else { prefix }.to_owned(),
        ));
    }
    if expected.starts_with('{') && actual.starts_with('{') {
        let expected_fields = parse_json_object_fields(expected)?;
        let actual_fields = parse_json_object_fields(actual)?;
        let expected_map = expected_fields.into_iter().collect::<BTreeMap<_, _>>();
        let actual_map = actual_fields.into_iter().collect::<BTreeMap<_, _>>();
        for (key, expected_value) in &expected_map {
            let path = json_child_path(prefix, key);
            let Some(actual_value) = actual_map.get(key) else {
                return Ok(Some(path));
            };
            if let Some(path) =
                first_json_difference(expected_value.trim(), actual_value.trim(), &path, depth + 1)?
            {
                return Ok(Some(path));
            }
        }
        if let Some(key) = actual_map
            .keys()
            .find(|key| !expected_map.contains_key(*key))
        {
            return Ok(Some(json_child_path(prefix, key)));
        }
        return Ok(None);
    }
    if expected.starts_with('[') && actual.starts_with('[') {
        let expected_values = parse_json_array_values(expected)?;
        let actual_values = parse_json_array_values(actual)?;
        let shared_len = expected_values.len().min(actual_values.len());
        for index in 0..shared_len {
            let path = format!("{}[{index}]", if prefix.is_empty() { "$" } else { prefix });
            if let Some(path) = first_json_difference(
                expected_values[index].trim(),
                actual_values[index].trim(),
                &path,
                depth + 1,
            )? {
                return Ok(Some(path));
            }
        }
        if expected_values.len() != actual_values.len() {
            return Ok(Some(
                if prefix.is_empty() { "$" } else { prefix }.to_owned(),
            ));
        }
        return Ok(None);
    }
    Ok(Some(
        if prefix.is_empty() { "$" } else { prefix }.to_owned(),
    ))
}

fn json_child_path(prefix: &str, key: &str) -> String {
    if prefix.is_empty() {
        key.to_owned()
    } else {
        format!("{prefix}.{key}")
    }
}

fn parse_json_object_fields(input: &str) -> std::result::Result<Vec<(String, &str)>, String> {
    let input = input.trim();
    let bytes = input.as_bytes();
    if bytes.first() != Some(&b'{') {
        return Err("expected JSON object".into());
    }
    let mut fields = Vec::new();
    let mut index = 1usize;
    loop {
        index = skip_json_whitespace(bytes, index);
        if bytes.get(index) == Some(&b'}') {
            index += 1;
            if skip_json_whitespace(bytes, index) != bytes.len() {
                return Err("trailing bytes after JSON object".into());
            }
            return Ok(fields);
        }
        if bytes.get(index) != Some(&b'\"') {
            return Err("expected JSON object key".into());
        }
        let key_end = json_string_end(input, index)?;
        let key = decode_json_string(&input[index..key_end])?;
        index = skip_json_whitespace(bytes, key_end);
        if bytes.get(index) != Some(&b':') {
            return Err(format!("expected `:` after JSON key `{key}`"));
        }
        index = skip_json_whitespace(bytes, index + 1);
        let value_start = index;
        let value_end = json_value_end(input, value_start)?;
        fields.push((key, input[value_start..value_end].trim()));
        index = skip_json_whitespace(bytes, value_end);
        match bytes.get(index) {
            Some(b',') => index += 1,
            Some(b'}') => continue,
            _ => return Err("expected `,` or `}` after JSON object value".into()),
        }
    }
}

fn parse_json_array_values(input: &str) -> std::result::Result<Vec<&str>, String> {
    let input = input.trim();
    let bytes = input.as_bytes();
    if bytes.first() != Some(&b'[') {
        return Err("expected JSON array".into());
    }
    let mut values = Vec::new();
    let mut index = 1usize;
    loop {
        index = skip_json_whitespace(bytes, index);
        if bytes.get(index) == Some(&b']') {
            index += 1;
            if skip_json_whitespace(bytes, index) != bytes.len() {
                return Err("trailing bytes after JSON array".into());
            }
            return Ok(values);
        }
        let value_start = index;
        let value_end = json_value_end(input, value_start)?;
        values.push(input[value_start..value_end].trim());
        index = skip_json_whitespace(bytes, value_end);
        match bytes.get(index) {
            Some(b',') => index += 1,
            Some(b']') => continue,
            _ => return Err("expected `,` or `]` after JSON array value".into()),
        }
    }
}

fn skip_json_whitespace(bytes: &[u8], mut index: usize) -> usize {
    while bytes
        .get(index)
        .is_some_and(|byte| matches!(byte, b' ' | b'\n' | b'\r' | b'\t'))
    {
        index += 1;
    }
    index
}

fn json_string_end(input: &str, start: usize) -> std::result::Result<usize, String> {
    let bytes = input.as_bytes();
    if bytes.get(start) != Some(&b'\"') {
        return Err("expected JSON string".into());
    }
    let mut index = start + 1;
    while index < bytes.len() {
        match bytes[index] {
            b'\\' => index = index.saturating_add(2),
            b'\"' => return Ok(index + 1),
            _ => index += 1,
        }
    }
    Err("unterminated JSON string".into())
}

fn json_value_end(input: &str, start: usize) -> std::result::Result<usize, String> {
    let bytes = input.as_bytes();
    let start = skip_json_whitespace(bytes, start);
    let Some(&first) = bytes.get(start) else {
        return Err("missing JSON value".into());
    };
    if first == b'\"' {
        return json_string_end(input, start);
    }
    if matches!(first, b'{' | b'[') {
        let mut stack = vec![first];
        let mut in_string = false;
        let mut escaped = false;
        for (index, &byte) in bytes.iter().enumerate().skip(start + 1) {
            if in_string {
                if escaped {
                    escaped = false;
                } else if byte == b'\\' {
                    escaped = true;
                } else if byte == b'\"' {
                    in_string = false;
                }
                continue;
            }
            match byte {
                b'\"' => in_string = true,
                b'{' | b'[' => stack.push(byte),
                b'}' => {
                    if stack.pop() != Some(b'{') {
                        return Err("mismatched JSON object delimiter".into());
                    }
                    if stack.is_empty() {
                        return Ok(index + 1);
                    }
                }
                b']' => {
                    if stack.pop() != Some(b'[') {
                        return Err("mismatched JSON array delimiter".into());
                    }
                    if stack.is_empty() {
                        return Ok(index + 1);
                    }
                }
                _ => {}
            }
        }
        return Err("unterminated JSON composite value".into());
    }
    let mut end = start;
    while end < bytes.len()
        && !matches!(
            bytes[end],
            b',' | b'}' | b']' | b' ' | b'\n' | b'\r' | b'\t'
        )
    {
        end += 1;
    }
    if end == start {
        Err("empty JSON primitive".into())
    } else {
        Ok(end)
    }
}

fn decode_json_string(token: &str) -> std::result::Result<String, String> {
    if !token.starts_with('"') || !token.ends_with('"') || token.len() < 2 {
        return Err("expected quoted JSON string".into());
    }
    let mut output = String::new();
    let mut chars = token[1..token.len() - 1].chars();
    while let Some(ch) = chars.next() {
        if ch != '\\' {
            output.push(ch);
            continue;
        }
        let escaped = chars.next().ok_or("truncated JSON escape")?;
        match escaped {
            '"' => output.push('"'),
            '\\' => output.push('\\'),
            '/' => output.push('/'),
            'b' => output.push('\u{0008}'),
            'f' => output.push('\u{000c}'),
            'n' => output.push('\n'),
            'r' => output.push('\r'),
            't' => output.push('\t'),
            'u' => {
                let digits = (0..4)
                    .map(|_| chars.next().ok_or("truncated JSON unicode escape"))
                    .collect::<std::result::Result<String, _>>()?;
                let value =
                    u32::from_str_radix(&digits, 16).map_err(|_| "invalid JSON unicode escape")?;
                output.push(char::from_u32(value).ok_or("invalid JSON unicode scalar")?);
            }
            _ => return Err("unsupported JSON escape".into()),
        }
    }
    Ok(output)
}

