fn dd_bluestein_upload_record(
    case_name: &str,
    logical_len: usize,
    batch_count: usize,
    grouped_batch: usize,
    bandwidth_boost: usize,
    device: DeviceProfile,
) -> Result<SchedulerSnapshotRecord> {
    let padded_len =
        upstream_bluestein_auto_padding(logical_len, batch_count, Precision::DoubleDouble, device)?;
    let child_config = FftConfig::new(vec![padded_len])
        .with_batch_count(batch_count)
        .with_precision(Precision::DoubleDouble)
        .with_bandwidth_boost(bandwidth_boost)
        .with_grouped_batch(0, grouped_batch)?
        .resolve_tuning_for_device(device);
    let child_plan = FftPlan::build_c2c_bluestein_child_for_device(
        child_config,
        device,
        crate::planner::C2cDeviceAxisClass::Strided,
    )?;
    let child = crate::double_double_recursive_ir::DoubleDoubleRecursiveFftIr::build_for_device(
        &child_plan,
        Direction::Forward,
        device,
    )?;
    let (upload_count, axis_split) =
        if let Some(schedule) = child.rader_forced_upload_schedule.as_ref() {
            (schedule.upload_count, schedule.axis_split.clone())
        } else if let Some(schedule) = child.stockham_upload_schedule.as_ref() {
            (schedule.upload_count, schedule.axis_split.clone())
        } else {
            return Err(VkFftError::UnsupportedKernelPath(
                "fixed grouped padded DD Bluestein child must retain a multi-upload schedule",
            ));
        };
    let used_shared_memory_bytes = if padded_len.is_power_of_two() {
        device.shared_memory_pow2_bytes
    } else {
        device.shared_memory_bytes
    };
    let max_sequence_len_shared =
        used_shared_memory_bytes / Precision::DoubleDouble.compute_complex_bytes();
    let policy = plan_gpu_scheduler_policy(Precision::DoubleDouble, device)?;
    let coalesced = policy
        .coalesced_memory_bytes
        .max(Precision::DoubleDouble.compute_complex_bytes());
    let max_sequence_len_strided = if coalesced > Precision::DoubleDouble.compute_complex_bytes() {
        used_shared_memory_bytes / coalesced
    } else {
        max_sequence_len_shared
    };
    Ok(SchedulerSnapshotRecord {
        case_name: case_name.to_owned(),
        backend: device.backend,
        vendor: device.vendor,
        precision: Precision::DoubleDouble,
        device,
        payload: SchedulerSnapshotPayload::DoubleDoubleRecursiveUpload {
            sequence_len: padded_len,
            batch_count,
            used_shared_memory_bytes,
            max_sequence_len_shared,
            max_sequence_len_strided,
            register_boost: 1,
            upload_count,
            axis_split,
        },
    })
}

fn dd_recursive_component_axis_block(
    node: &crate::double_double_recursive_ir::DoubleDoubleRecursiveFftNodeIr,
) -> Option<StockhamAxisBlockSchedule> {
    use crate::double_double_recursive_ir::DoubleDoubleRecursiveFftNodeIr;
    match node {
        DoubleDoubleRecursiveFftNodeIr::Stockham(stockham) => stockham.axis_batch_block,
        DoubleDoubleRecursiveFftNodeIr::CooleyTukey(cooley) => cooley.pack_right.axis_batch_block,
        DoubleDoubleRecursiveFftNodeIr::DirectRader(rader) => rader.axis_batch_block,
        DoubleDoubleRecursiveFftNodeIr::FftRader(rader) => rader.caller_axis_batch_block,
        DoubleDoubleRecursiveFftNodeIr::Bluestein(_) => None,
    }
}

fn dd_bluestein_axis_block_records(
    case_prefix: &str,
    logical_len: usize,
    outer_batch_count: usize,
    fastest_axis_len: usize,
    grouped_batch: usize,
    bandwidth_boost: usize,
    device: DeviceProfile,
) -> Result<Vec<SchedulerSnapshotRecord>> {
    let padded_len = upstream_bluestein_auto_padding(
        logical_len,
        outer_batch_count,
        Precision::DoubleDouble,
        device,
    )?;
    let config = FftConfig::new(vec![logical_len, fastest_axis_len])
        .with_batch_count(outer_batch_count)
        .with_grouped_batch(0, grouped_batch)?
        .with_bandwidth_boost(bandwidth_boost)
        .with_zero_padding(0, 1, 2)?
        .with_precision(Precision::DoubleDouble)
        .resolve_tuning_for_device(device);
    let transform = crate::TransformIr::build(config, Direction::Forward, device)?;
    let crate::TransformIr::ComplexNdDoubleDouble(nd) = transform else {
        return Err(VkFftError::InvalidKernelIr(
            "fixed grouped padded DD Bluestein snapshot must build ND C2C",
        ));
    };
    let outer = nd
        .axes
        .iter()
        .find(|axis| axis.axis == 0)
        .ok_or(VkFftError::InvalidKernelIr(
            "fixed grouped padded DD Bluestein snapshot lost outer axis",
        ))?;
    let crate::DoubleDoubleOneDimIr::Bluestein(bluestein) = &outer.transform else {
        return Err(VkFftError::InvalidKernelIr(
            "fixed grouped padded DD Bluestein snapshot did not select Bluestein",
        ));
    };
    if bluestein.convolution_len != padded_len {
        return Err(VkFftError::InvalidKernelIr(
            "fixed grouped padded DD Bluestein snapshot padding changed",
        ));
    }
    let crate::DoubleDoubleBluesteinConvolutionIr::Recursive(child) = &bluestein.forward_fft else {
        return Err(VkFftError::InvalidKernelIr(
            "fixed grouped padded DD Bluestein snapshot child must remain recursive",
        ));
    };
    let (upload_count, axis_split) =
        if let Some(schedule) = child.rader_forced_upload_schedule.as_ref() {
            (schedule.upload_count, schedule.axis_split.clone())
        } else if let Some(schedule) = child.stockham_upload_schedule.as_ref() {
            (schedule.upload_count, schedule.axis_split.clone())
        } else {
            return Err(VkFftError::UnsupportedKernelPath(
                "fixed grouped padded DD Bluestein child must retain multi-upload scheduling",
            ));
        };
    if upload_count != 2 || axis_split.len() != 2 {
        return Err(VkFftError::UnsupportedKernelPath(
            "fixed grouped padded DD Bluestein child must retain two uploads",
        ));
    }
    let crate::double_double_recursive_ir::DoubleDoubleRecursiveFftNodeIr::CooleyTukey(root) =
        &child.root
    else {
        return Err(VkFftError::UnsupportedKernelPath(
            "fixed grouped padded DD Bluestein child must retain a Cooley root",
        ));
    };
    let components = [&root.left, &root.right];
    let mut records = Vec::with_capacity(2);
    for (axis_upload_id, node) in components.into_iter().enumerate() {
        if node.logical_len() != axis_split[axis_upload_id] {
            return Err(VkFftError::InvalidKernelIr(
                "fixed grouped padded DD Bluestein recursive component order changed",
            ));
        }
        let block =
            dd_recursive_component_axis_block(node).ok_or(VkFftError::UnsupportedKernelPath(
                "fixed grouped padded DD Bluestein recursive component lost its physical block",
            ))?;
        records.push(axis_block_record(
            &format!("{case_prefix}-u{axis_upload_id}"),
            Precision::DoubleDouble,
            device,
            node.logical_len(),
            node.batch_count(),
            Some(axis_upload_id),
            node.batch_count(),
            block,
        ));
    }
    Ok(records)
}

