fn dd_nested_n392_nd_dct1_upload_record(
    case_name: &str,
    device: DeviceProfile,
) -> Result<SchedulerSnapshotRecord> {
    let recursive = dd_nested_n392_nd_dct1_recursive(device)?;
    if recursive.logical_len != 782 {
        return Err(VkFftError::InvalidKernelIr(
            "fixed DD N392 ND DCT-I snapshot changed the N782 reduction length",
        ));
    }
    let (force_rader_two_upload, upload_count, axis_split) =
        if let Some(schedule) = recursive.rader_forced_upload_schedule.as_ref() {
            (
                matches!(
                    schedule.reason,
                    crate::scheduler::RaderUploadReason::ForcedRaderPressure
                ),
                schedule.upload_count,
                schedule.axis_split.clone(),
            )
        } else if let Some(schedule) = recursive.stockham_upload_schedule.as_ref() {
            (false, schedule.upload_count, schedule.axis_split.clone())
        } else {
            (false, 1, vec![782])
        };
    Ok(SchedulerSnapshotRecord {
        case_name: case_name.to_owned(),
        backend: device.backend,
        vendor: device.vendor,
        precision: Precision::DoubleDouble,
        device,
        payload: SchedulerSnapshotPayload::RaderUpload {
            sequence_len: 782,
            force_rader_two_upload,
            upload_count,
            axis_split,
        },
    })
}

fn dd_nested_n392_nd_dct1_block_records(
    case_prefix: &str,
    device: DeviceProfile,
) -> Result<Vec<SchedulerSnapshotRecord>> {
    let recursive = dd_nested_n392_nd_dct1_recursive(device)?;
    let axis_split = if let Some(schedule) = recursive.rader_forced_upload_schedule.as_ref() {
        schedule.axis_split.clone()
    } else if let Some(schedule) = recursive.stockham_upload_schedule.as_ref() {
        schedule.axis_split.clone()
    } else {
        vec![782]
    };
    if axis_split.len() == 1 {
        let block = dd_recursive_component_axis_block(&recursive.root).ok_or(
            VkFftError::InvalidKernelIr(
                "fixed DD N392 ND DCT-I N782 snapshot lost its root physical block",
            ),
        )?;
        return Ok(vec![axis_block_record(
            &format!("{case_prefix}-u0"),
            Precision::DoubleDouble,
            device,
            recursive.root.logical_len(),
            recursive.root.batch_count(),
            Some(0),
            recursive.root.batch_count(),
            block,
        )]);
    }
    if axis_split.len() != 2 {
        return Err(VkFftError::InvalidKernelIr(
            "fixed DD N392 ND DCT-I snapshot expected one or two uploads",
        ));
    }
    let crate::double_double_recursive_ir::DoubleDoubleRecursiveFftNodeIr::CooleyTukey(root) =
        &recursive.root
    else {
        return Err(VkFftError::InvalidKernelIr(
            "fixed DD N392 ND DCT-I two-upload snapshot lost Cooley root",
        ));
    };
    let nodes = [&root.left, &root.right];
    let mut records = Vec::with_capacity(2);
    for (axis_upload_id, node) in nodes.into_iter().enumerate() {
        if node.logical_len() != axis_split[axis_upload_id] {
            return Err(VkFftError::InvalidKernelIr(
                "fixed DD N392 ND DCT-I upload component order changed",
            ));
        }
        let block = dd_recursive_component_axis_block(node).ok_or(VkFftError::InvalidKernelIr(
            "fixed DD N392 ND DCT-I upload component lost its physical block",
        ))?;
        records.push(axis_block_record(
            &format!("{case_prefix}-u{axis_upload_id}"),
            Precision::DoubleDouble,
            device,
            node.logical_len(),
            node.batch_count(),
            Some(axis_upload_id),
            node.batch_count(),
            block,
        ));
    }
    Ok(records)
}

