fn forced_rader_two_upload_axis_block_records_from_ir(
    case_prefix: &str,
    device: DeviceProfile,
    ir: &crate::double_double_recursive_ir::DoubleDoubleRecursiveFftIr,
) -> Result<Vec<SchedulerSnapshotRecord>> {
    let axis_split: [usize; 2] = ir
        .rader_forced_upload_schedule
        .as_ref()
        .and_then(|schedule| schedule.axis_split.as_slice().try_into().ok())
        .ok_or(crate::VkFftError::UnsupportedKernelPath(
            "fixed cross-vendor DD Rader snapshot must retain a two-upload split",
        ))?;
    let mut records = Vec::with_capacity(2);
    for (upload_id, &expected_len) in axis_split.iter().enumerate() {
        let mapped_component = if upload_id == 0 {
            ir.forced_rader_two_upload_mapped_low_component()?
        } else {
            ir.forced_rader_two_upload_mapped_high_component()?
        };
        if let Some(node) = mapped_component {
            if node.logical_len() != expected_len {
                return Err(crate::VkFftError::UnsupportedKernelPath(
                    "fixed cross-vendor DD Rader mapped component must match the scheduler split",
                ));
            }
            let block = recursive_node_axis_block(&node).ok_or(
                crate::VkFftError::UnsupportedKernelPath(
                    "fixed cross-vendor DD Rader component must have a physical axis block",
                ),
            )?;
            records.push(axis_block_record(
                &format!("{case_prefix}-u{upload_id}"),
                Precision::DoubleDouble,
                device,
                node.logical_len(),
                node.batch_count(),
                Some(upload_id),
                node.batch_count(),
                block,
            ));
            continue;
        }

        let mapped_stockham = if upload_id == 0 {
            ir.forced_rader_two_upload_mapped_low_stockham()?
        } else {
            ir.forced_rader_two_upload_mapped_high_stockham()?
        };
        let Some((stockham, _mapping)) = mapped_stockham else {
            return Err(crate::VkFftError::UnsupportedKernelPath(
                "fixed cross-vendor DD Rader snapshot must materialize each upload as a component or Stockham node",
            ));
        };
        if stockham.sequence_len != expected_len {
            return Err(crate::VkFftError::UnsupportedKernelPath(
                "fixed cross-vendor DD Rader mapped Stockham must match the scheduler split",
            ));
        }
        let block = stockham
            .axis_batch_block
            .ok_or(crate::VkFftError::UnsupportedKernelPath(
                "fixed cross-vendor DD Rader Stockham must have a physical axis block",
            ))?;
        records.push(axis_block_record(
            &format!("{case_prefix}-u{upload_id}"),
            Precision::DoubleDouble,
            device,
            stockham.sequence_len,
            stockham.batch_count,
            Some(upload_id),
            stockham.batch_count,
            block,
        ));
    }
    Ok(records)
}

fn dd_recursive_root_axis_block_record_with_tuning(
    case_name: &str,
    sequence_len: usize,
    device: DeviceProfile,
    tuning: PlannerTuning,
) -> Result<SchedulerSnapshotRecord> {
    let plan = crate::FftPlan::build_for_device(
        crate::FftConfig::new(vec![sequence_len])
            .with_precision(Precision::DoubleDouble)
            .with_tuning(tuning),
        device,
    )?;
    let ir = crate::double_double_recursive_ir::DoubleDoubleRecursiveFftIr::build_for_device(
        &plan,
        crate::Direction::Forward,
        device,
    )?;
    if ir.rader_forced_upload_schedule.is_some() {
        return Err(crate::VkFftError::UnsupportedKernelPath(
            "fixed DD recursive root snapshot must remain single upload",
        ));
    }
    let block =
        recursive_node_axis_block(&ir.root).ok_or(crate::VkFftError::UnsupportedKernelPath(
            "fixed DD recursive root snapshot must retain a physical axis block",
        ))?;
    Ok(axis_block_record(
        case_name,
        Precision::DoubleDouble,
        device,
        ir.root.logical_len(),
        ir.root.batch_count(),
        Some(0),
        ir.root.batch_count(),
        block,
    ))
}

