fn dd_stockham_upload_axis_block_records(
    case_prefix: &str,
    sequence_len: usize,
    device: DeviceProfile,
) -> Result<Vec<SchedulerSnapshotRecord>> {
    let plan = FftPlan::build_for_device(
        FftConfig::new(vec![sequence_len]).with_precision(Precision::DoubleDouble),
        device,
    )?;
    let ir = crate::double_double_recursive_ir::DoubleDoubleRecursiveFftIr::build_for_device(
        &plan,
        Direction::Forward,
        device,
    )?;
    let schedule = ir
        .stockham_upload_schedule
        .as_ref()
        .ok_or(VkFftError::InvalidKernelIr(
            "fixed DD Stockham-upload snapshot is missing upload metadata",
        ))?;
    let mut records = Vec::with_capacity(schedule.upload_count);
    match schedule.upload_count {
        2 => {
            let four_step = ir
                .two_upload_four_step_plan
                .ok_or(VkFftError::InvalidKernelIr(
                    "fixed DD two-upload Stockham snapshot is missing Four-step metadata",
                ))?;
            for (axis_upload_id, fft_len, block) in [
                (0usize, four_step.left_len, four_step.left_axis_block),
                (1usize, four_step.right_len, four_step.right_axis_block),
            ] {
                let transform_count = sequence_len / fft_len;
                records.push(axis_block_record(
                    &format!("{case_prefix}-u{axis_upload_id}"),
                    Precision::DoubleDouble,
                    device,
                    fft_len,
                    transform_count,
                    Some(axis_upload_id),
                    transform_count,
                    block,
                ));
            }
        }
        3 => {
            let four_step = ir
                .three_upload_four_step_plan
                .ok_or(VkFftError::InvalidKernelIr(
                    "fixed DD three-upload Stockham snapshot is missing Four-step metadata",
                ))?;
            for (axis_upload_id, fft_len, block) in [
                (
                    0usize,
                    four_step.axis_split[0],
                    four_step.upload0_axis_block,
                ),
                (
                    1usize,
                    four_step.axis_split[1],
                    four_step.upload1_axis_block,
                ),
                (
                    2usize,
                    four_step.axis_split[2],
                    four_step.upload2_axis_block,
                ),
            ] {
                let transform_count = sequence_len / fft_len;
                records.push(axis_block_record(
                    &format!("{case_prefix}-u{axis_upload_id}"),
                    Precision::DoubleDouble,
                    device,
                    fft_len,
                    transform_count,
                    Some(axis_upload_id),
                    transform_count,
                    block,
                ));
            }
        }
        _ => {
            return Err(VkFftError::InvalidKernelIr(
                "fixed DD Stockham-upload snapshot must use two or three uploads",
            ));
        }
    }
    Ok(records)
}

