    #[test]
    fn parameterized_axis2_grouped_batch_gate_is_independent_from_target_override() {
        let mut amd = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Amd);
        amd.shared_memory_bytes = 8 * 1024;
        amd.shared_memory_pow2_bytes = 8 * 1024;
        amd.max_threads_per_block = 256;
        amd.max_workgroup_size = [256, 256, 64];
        amd.coalesced_memory_bytes = 32;
        let probe = SchedulerRaderUploadProbe {
            case_name: "probe-amd-dd-n1088-axis2-g3".to_owned(),
            sequence_len: 1_088,
            precision: Precision::DoubleDouble,
            device: amd,
            strided_axis: true,
            fastest_axis_len: 8,
            bandwidth_boost: 0,
            batch_count: 1,
            grouped_batch_override: Some(3),
            perform_zero_padding: false,
            min_rader_direct_prime: 11,
            max_rader_direct_prime: 29,
            min_rader_fft_prime: 19,
            max_rader_fft_prime: 16_384,
        };
        let gate0 = scheduler_rader_upload_axis_block_probe_records_with_context(
            &probe,
            SchedulerPhysicalAxisProbeContext {
                upstream_axis_id: 2,
                middle_axis_len: 4,
                axis1_grouped_batch_override: None,
            },
        )
        .unwrap();
        let gate8 = scheduler_rader_upload_axis_block_probe_records_with_context(
            &probe,
            SchedulerPhysicalAxisProbeContext {
                upstream_axis_id: 2,
                middle_axis_len: 4,
                axis1_grouped_batch_override: Some(8),
            },
        )
        .unwrap();

        let block = |records: &[SchedulerSnapshotRecord], upload_id: usize| {
            let record = records
                .iter()
                .find(|record| record.case_name.ends_with(&format!("-u{upload_id}")))
                .unwrap_or_else(|| panic!("missing axis2 upload {upload_id}"));
            let SchedulerSnapshotPayload::AxisBlock {
                transform_count,
                block,
                ..
            } = &record.payload
            else {
                panic!("axis2 upload {upload_id} changed snapshot kind");
            };
            assert!(block.transforms_on_x);
            assert!(!block.axis_swapped);
            (
                *transform_count,
                block.grouped_batch,
                [block.local_size_x, block.local_size_y],
            )
        };

        assert_eq!(block(&gate0, 0), (1_088, 3, [3, 4]));
        assert_eq!(block(&gate0, 1), (1_024, 3, [3, 18]));
        assert_eq!(block(&gate8, 0), (1_088, 8, [8, 4]));
        assert_eq!(block(&gate8, 1), (1_024, 7, [7, 18]));
    }

    #[test]
    fn axis2_grouped_probe_rejects_upstream_thread_overflow_but_keeps_valid_gate() {
        let mut amd = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Amd);
        amd.shared_memory_bytes = 8 * 1024;
        amd.shared_memory_pow2_bytes = 8 * 1024;
        amd.max_threads_per_block = 256;
        amd.max_workgroup_size = [256, 256, 64];
        amd.coalesced_memory_bytes = 32;
        let probe = SchedulerRaderUploadProbe {
            case_name: "probe-amd-f64f32-n8789-axis2-g3".to_owned(),
            sequence_len: 8_789,
            precision: Precision::F64ComputeF32Storage,
            device: amd,
            strided_axis: true,
            fastest_axis_len: 8,
            bandwidth_boost: 0,
            batch_count: 5,
            grouped_batch_override: Some(3),
            perform_zero_padding: false,
            min_rader_direct_prime: 17,
            max_rader_direct_prime: 89,
            min_rader_fft_prime: 29,
            max_rader_fft_prime: 16_384,
        };
        let invalid = scheduler_rader_upload_axis_block_probe_records_with_context(
            &probe,
            SchedulerPhysicalAxisProbeContext {
                upstream_axis_id: 2,
                middle_axis_len: 4,
                axis1_grouped_batch_override: None,
            },
        )
        .unwrap_err();
        assert!(matches!(
            invalid,
            VkFftError::UnsupportedKernelPath(
                "grouped higher-axis forced-Rader upload workgroup is not executable on this device"
            )
        ));

        // Pinned upstream's literal gate-0 branch produces u0=[85,99] here, which
        // exceeds its own 256-thread device limit. With groupedBatch[1]=8 the same
        // target groupedBatch[2]=3 path stays physically valid and is parity-locked.
        let valid = scheduler_rader_upload_axis_block_probe_records_with_context(
            &probe,
            SchedulerPhysicalAxisProbeContext {
                upstream_axis_id: 2,
                middle_axis_len: 4,
                axis1_grouped_batch_override: Some(8),
            },
        )
        .unwrap();
        let block = |upload_id: usize| {
            let record = valid
                .iter()
                .find(|record| record.case_name.ends_with(&format!("-u{upload_id}")))
                .unwrap();
            let SchedulerSnapshotPayload::AxisBlock {
                transform_count,
                block,
                ..
            } = &record.payload
            else {
                panic!("axis2 N8789 upload changed snapshot kind");
            };
            (
                *transform_count,
                block.threads_per_transform,
                block.grouped_batch,
                [block.local_size_x, block.local_size_y],
            )
        };
        assert_eq!(block(0), (7_520, 99, 2, [2, 99]));
        assert_eq!(block(1), (29_920, 24, 8, [8, 24]));
    }

    #[test]
    fn parameterized_axis2_bandwidth_boost_changes_upload_split_under_asymmetric_gate() {
        let mut intel = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Intel);
        intel.shared_memory_bytes = 32 * 1024;
        intel.shared_memory_pow2_bytes = 32 * 1024;
        intel.max_threads_per_block = 1024;
        intel.max_workgroup_size = [1024, 1024, 64];
        intel.coalesced_memory_bytes = 64;
        let probe = |bandwidth_boost: usize| SchedulerRaderUploadProbe {
            case_name: format!("probe-intel-f32-n278528-axis2-b{bandwidth_boost}"),
            sequence_len: 278_528,
            precision: Precision::F32,
            device: intel,
            strided_axis: true,
            fastest_axis_len: 8,
            bandwidth_boost,
            batch_count: 5,
            grouped_batch_override: Some(3),
            perform_zero_padding: false,
            min_rader_direct_prime: 17,
            max_rader_direct_prime: 17,
            min_rader_fft_prime: 17,
            max_rader_fft_prime: 16_384,
        };
        let b0_probe = probe(0);
        let b2_probe = probe(2);
        let split = |probe: &SchedulerRaderUploadProbe| {
            let record = scheduler_rader_upload_probe_record(probe).unwrap();
            let SchedulerSnapshotPayload::RaderUpload {
                upload_count,
                axis_split,
                ..
            } = record.payload
            else {
                panic!("axis2 bandwidth probe changed logical snapshot kind");
            };
            (upload_count, axis_split)
        };
        assert_eq!(split(&b0_probe), (3, vec![64, 68, 64]));
        assert_eq!(split(&b2_probe), (2, vec![544, 512]));

        let context = SchedulerPhysicalAxisProbeContext {
            upstream_axis_id: 2,
            middle_axis_len: 4,
            axis1_grouped_batch_override: Some(8),
        };
        let b0 = scheduler_rader_upload_axis_block_probe_records_with_context(&b0_probe, context)
            .unwrap();
        let b2 = scheduler_rader_upload_axis_block_probe_records_with_context(&b2_probe, context)
            .unwrap();
        let block = |records: &[SchedulerSnapshotRecord], upload_id: usize| {
            let record = records
                .iter()
                .find(|record| record.case_name.ends_with(&format!("-u{upload_id}")))
                .unwrap_or_else(|| panic!("missing axis2 bandwidth upload {upload_id}"));
            let SchedulerSnapshotPayload::AxisBlock {
                transform_count,
                block,
                ..
            } = &record.payload
            else {
                panic!("axis2 bandwidth upload changed physical snapshot kind");
            };
            (
                *transform_count,
                block.threads_per_transform,
                block.grouped_batch,
                [block.local_size_x, block.local_size_y],
            )
        };
        assert_eq!(block(&b0, 0), (696_320, 8, 8, [8, 8]));
        assert_eq!(block(&b0, 1), (655_360, 5, 8, [8, 5]));
        assert_eq!(block(&b0, 2), (696_320, 8, 8, [8, 8]));
        assert_eq!(block(&b2, 0), (81_920, 34, 8, [8, 34]));
        assert_eq!(block(&b2, 1), (87_040, 64, 8, [8, 64]));
    }

